head.script:
scwin.onpageload = function() {
    ipt_test1.setValue(99991212);
};
scwin.onpageunload = function() {};

scwin.checkVal1 = function() {
	return (document.getElementById('ipt_test1_calendar_selectbox_year_label') || document.getElementById('mf_ipt_test1_calendar_selectbox_year_label')).innerText == '2030년';
}
scwin.checkVal2 = function() {
	return (document.getElementById('ipt_test1_calendar_selectbox_month_label') || document.getElementById('mf_ipt_test1_calendar_selectbox_month_label')).innerText == '1월';
}
